DROP TABLE IF EXISTS `listening_groups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `listening_groups` (
  `id` bigint unsigned NOT NULL,
  `exam_id` bigint unsigned NOT NULL,
  `section_id` bigint unsigned NOT NULL,
  `group_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `group_number` tinyint unsigned NOT NULL,
  `title` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_start` tinyint unsigned NOT NULL,
  `question_end` tinyint unsigned NOT NULL,
  `instructions` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` tinyint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_exam_listening_group` (`exam_id`,`sort_order`),
  KEY `fk_groups_section` (`section_id`),
  CONSTRAINT `fk_groups_exam` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_groups_section` FOREIGN KEY (`section_id`) REFERENCES `sections` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

