DROP TABLE IF EXISTS `matching_paragraphs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `matching_paragraphs` (
  `id` bigint unsigned NOT NULL,
  `passage_id` bigint unsigned NOT NULL,
  `paragraph_label` char(1) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` tinyint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_matching_paragraph` (`passage_id`,`paragraph_label`),
  CONSTRAINT `fk_paragraphs_passage` FOREIGN KEY (`passage_id`) REFERENCES `passages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

