CREATE TABLE `passages` (
  `id` bigint unsigned NOT NULL,
  `exam_id` bigint unsigned NOT NULL,
  `section_id` bigint unsigned NOT NULL,
  `passage_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `passage_index` tinyint unsigned NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` tinyint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_exam_passage` (`exam_id`,`passage_type`,`passage_index`),
  KEY `idx_passage_type` (`passage_type`),
  KEY `fk_passages_section` (`section_id`),
  CONSTRAINT `fk_passages_exam` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_passages_section` FOREIGN KEY (`section_id`) REFERENCES `sections` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
