--
-- Table structure for table `word_bank_entries`
--

DROP TABLE IF EXISTS `word_bank_entries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `word_bank_entries` (
  `id` bigint unsigned NOT NULL,
  `passage_id` bigint unsigned NOT NULL,
  `option_label` char(1) COLLATE utf8mb4_unicode_ci NOT NULL,
  `word_text` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` tinyint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_passage_word` (`passage_id`,`option_label`),
  CONSTRAINT `fk_words_passage` FOREIGN KEY (`passage_id`) REFERENCES `passages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

