--
-- Table structure for table `writing_prompts`
--

DROP TABLE IF EXISTS `writing_prompts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `writing_prompts` (
  `id` bigint unsigned NOT NULL,
  `exam_id` bigint unsigned NOT NULL,
  `section_id` bigint unsigned NOT NULL,
  `prompt_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `word_count_min` smallint unsigned NOT NULL,
  `word_count_max` smallint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_exam_writing` (`exam_id`),
  KEY `fk_writing_section` (`section_id`),
  CONSTRAINT `fk_writing_exam` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_writing_section` FOREIGN KEY (`section_id`) REFERENCES `sections` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

